data.content:
MSTest **does not have** `Assert.IsGreaterThan`, `Assert.IsInRange`, or similar comparison assertions. Here's what to use instead:

| Need | Approach |
|---|---|
| Value > X | `Assert.IsTrue(value > x)` |
| Value in range | `Assert.IsTrue(value >= lo && value <= hi)` |
| Exact match | `Assert.AreEqual(expected, actual)` |
| Float tolerance | `Assert.AreEqual(expected, actual, delta)` |
| Exception thrown | `Assert.ThrowsException<T>(action)` |

The `double` overload of `Assert.AreEqual` with a **delta** parameter is the key one for your scoring math — it handles floating-point imprecision.

Here's a complete test class:

```csharp
using Contoso.Scoring;

namespace Contoso.Scoring.Tests;

[TestClass]
public sealed class ScoreCalculatorTests
{
    private readonly ScoreCalculator _calc = new();

    // ── CalculatePercentage ──

    [TestMethod]
    public void CalculatePercentage_PerfectScore_Returns100()
    {
        Assert.AreEqual(100.0, _calc.CalculatePercentage(10, 10), 0.001);
    }

    [TestMethod]
    public void CalculatePercentage_ZeroCorrect_Returns0()
    {
        Assert.AreEqual(0.0, _calc.CalculatePercentage(0, 10), 0.001);
    }

    [TestMethod]
    public void CalculatePercentage_PartialScore_ReturnsExpected()
    {
        Assert.AreEqual(75.0, _calc.CalculatePercentage(3, 4), 0.001);
    }

    [TestMethod]
    public void CalculatePercentage_RepeatingDecimal_IsWithinTolerance()
    {
        // 1/3 = 33.333...
        Assert.AreEqual(33.333, _calc.CalculatePercentage(1, 3), 0.001);
    }

    [TestMethod]
    public void CalculatePercentage_ZeroTotal_Throws()
    {
        Assert.ThrowsException<ArgumentOutOfRangeException>(
            () => _calc.CalculatePercentage(0, 0));
    }

    [TestMethod]
    public void CalculatePercentage_NegativeTotal_Throws()
    {
        Assert.ThrowsException<ArgumentOutOfRangeException>(
            () => _calc.CalculatePercentage(0, -1));
    }

    [TestMethod]
    public void CalculatePercentage_NegativeCorrect_Throws()
    {
        Assert.ThrowsException<ArgumentOutOfRangeException>(
            () => _calc.CalculatePercentage(-1, 10));
    }

    [TestMethod]
    public void CalculatePercentage_CorrectExceedsTotal_Throws()
    {
        Assert.ThrowsException<ArgumentOutOfRangeException>(
            () => _calc.CalculatePercentage(11, 10));
    }

    // ── GetGrade boundary tests ──

    [DataTestMethod]
    [DataRow(100.0, "A")]
    [DataRow(90.0,  "A")]   // boundary: exactly 90
    [DataRow(89.99, "B")]   // just below A
    [DataRow(80.0,  "B")]
    [DataRow(79.99, "C")]
    [DataRow(70.0,  "C")]
    [DataRow(69.99, "D")]
    [DataRow(60.0,  "D")]
    [DataRow(59.99, "F")]
    [DataRow(0.0,   "F")]
    public void GetGrade_AtBoundaries_ReturnsExpectedGrade(
        double percentage, string expected)
    {
        Assert.AreEqual(expected, _calc.GetGrade(percentage));
    }

    // ── NormalizeScore ──

    [TestMethod]
    public void NormalizeScore_HalfOfMax_Returns50()
    {
        Assert.AreEqual(50.0, _calc.NormalizeScore(25, 50), 0.001);
    }

    [TestMethod]
    public void NormalizeScore_ExceedsMax_ClampedTo100()
    {
        Assert.AreEqual(100.0, _calc.NormalizeScore(120, 100), 0.001);
    }

    [TestMethod]
    public void NormalizeScore_Zero_Returns0()
    {
        Assert.AreEqual(0.0, _calc.NormalizeScore(0, 50), 0.001);
    }

    [TestMethod]
    public void NormalizeScore_NegativeRaw_Throws()
    {
        Assert.ThrowsException<ArgumentOutOfRangeException>(
            () => _calc.NormalizeScore(-1, 50));
    }

    [TestMethod]
    public void NormalizeScore_ZeroMax_Throws()
    {
        Assert.ThrowsException<ArgumentOutOfRangeException>(
            () => _calc.NormalizeScore(10, 0));
    }
}
```

**Key patterns used:**
- **`Assert.AreEqual(expected, actual, 0.001)`** — the third `delta` arg handles floating-point comparison (e.g., `33.333...`)
- **`Assert.ThrowsException<T>`** — verifies guard clauses throw
- **`[DataTestMethod]` + `[DataRow]`** — tests every grade boundary in one method, hitting both the exact cutoff and just-below values
